xpath.script:
(function () {
  if (!window.Element || !Element.prototype.attachShadow) { return; }
  var originalAttachShadow = Element.prototype.attachShadow;
  Element.prototype.attachShadow = function (init) {
    var root = originalAttachShadow.call(this, Object.assign({}, init, { mode: 'open' }));
    function removeBadge() {
      root.querySelectorAll('a[href*="testimonials-slider-widget"]').forEach(function (el) {
        el.remove();
      });
    }
    removeBadge();
    new MutationObserver(removeBadge).observe(root, { childList: true, subtree: true });
    return root;
  };
})();
